/* ─── Keyframes ──────────────────────────────────────────────────── */
function useContactsKeyframes() {
  useEffect(() => {
    const id = 'contacts-kf';
    if (document.getElementById(id)) return;
    const s = document.createElement('style');
    s.id = id;
    s.textContent = `
      @import url('https://fonts.googleapis.com/css2?family=Playfair+Display:wght@700;900&family=Inter:wght@300;400;500;600&display=swap');

      @keyframes ct-fadeUp   { from{opacity:0;transform:translateY(28px)} to{opacity:1;transform:translateY(0)} }
      @keyframes ct-fadeIn   { from{opacity:0} to{opacity:1} }
      @keyframes ct-slideR   { from{opacity:0;transform:translateX(-24px)} to{opacity:1;transform:translateX(0)} }
      @keyframes ct-slideL   { from{opacity:0;transform:translateX(28px)}  to{opacity:1;transform:translateX(0)} }
      @keyframes ct-scaleIn  { from{opacity:0;transform:scale(0.93) translateY(18px)} to{opacity:1;transform:scale(1) translateY(0)} }
      @keyframes ct-spin     { to{transform:rotate(360deg)} }
      @keyframes ct-lineGrow { from{transform:scaleX(0)} to{transform:scaleX(1)} }

      /* Icon badge tilt on card hover */
      @keyframes ct-tilt     { 0%{transform:rotate(0deg) scale(1)} 40%{transform:rotate(-8deg) scale(1.12)} 70%{transform:rotate(5deg) scale(1.08)} 100%{transform:rotate(0deg) scale(1)} }

      /* Map ping pulse */
      @keyframes ct-ping     { 0%{transform:scale(1);opacity:0.6} 100%{transform:scale(2.8);opacity:0} }

      /* Map radar rings draw in */
      @keyframes ct-radarIn  { from{opacity:0;r:0} to{opacity:1} }

      /* Submit button shimmer sweep */
      @keyframes ct-shimmer  { 0%{left:-100%} 100%{left:200%} }

      /* Success icon pop with bounce */
      @keyframes ct-checkPop { 0%{transform:scale(0) rotate(-25deg);opacity:0} 60%{transform:scale(1.2) rotate(5deg);opacity:1} 80%{transform:scale(0.95) rotate(-2deg)} 100%{transform:scale(1) rotate(0);opacity:1} }

      /* Success rings expand */
      @keyframes ct-ringOut  { 0%{transform:scale(0.4);opacity:0.8} 100%{transform:scale(1.8);opacity:0} }

      /* Form field label float up on focus */
      @keyframes ct-labelUp  { from{transform:translateY(0);opacity:0.45} to{transform:translateY(0);opacity:1} }

      /* Error shake */
      @keyframes ct-shake    { 0%,100%{transform:translateX(0)} 20%{transform:translateX(-6px)} 40%{transform:translateX(5px)} 60%{transform:translateX(-4px)} 80%{transform:translateX(3px)} }

      /* Arrow nudge on card hover */
      @keyframes ct-arrowNudge { 0%,100%{transform:translateX(0)} 50%{transform:translateX(4px)} }

      .ct-card {
        transition: transform 0.32s cubic-bezier(.22,1,.36,1),
                    box-shadow 0.32s ease,
                    border-color 0.25s ease;
      }
      .ct-card:hover {
        transform: translateY(-4px) !important;
        box-shadow: 0 16px 48px rgba(0,67,114,0.13) !important;
        border-color: rgba(0,67,114,0.18) !important;
      }
      .ct-card:hover .ct-icon-badge {
        animation: ct-tilt 0.5s cubic-bezier(.22,1,.36,1) forwards;
        background: linear-gradient(135deg, rgba(0,67,114,0.14), rgba(0,86,154,0.09)) !important;
      }
      .ct-card:hover .ct-arrow {
        animation: ct-arrowNudge 0.45s ease forwards;
        color: rgba(0,67,114,0.55) !important;
      }

      .ct-input {
        transition: border-color 0.22s ease, box-shadow 0.22s ease, background 0.22s ease;
        outline: none;
      }
      .ct-input:focus {
        border-color: rgba(0,67,114,0.5) !important;
        box-shadow: 0 0 0 3.5px rgba(0,67,114,0.09) !important;
        background: rgba(0,67,114,0.025) !important;
      }
      .ct-input::placeholder { color: rgba(0,0,0,0.28); }

      .ct-submit {
        position: relative; overflow: hidden;
        transition: all 0.26s cubic-bezier(.22,1,.36,1);
      }
      .ct-submit:not(:disabled)::after {
        content: '';
        position: absolute; top: 0; width: 60%; height: 100%;
        background: linear-gradient(90deg, transparent, rgba(255,255,255,0.15), transparent);
        transform: skewX(-20deg);
        left: -100%;
      }
      .ct-submit:hover:not(:disabled) {
        background: linear-gradient(135deg, #003d6b, #00569a) !important;
        transform: translateY(-2px);
        box-shadow: 0 10px 28px rgba(0,67,114,0.32) !important;
      }
      .ct-submit:hover:not(:disabled)::after {
        animation: ct-shimmer 0.7s ease forwards;
      }
      .ct-submit:active:not(:disabled) { transform: translateY(0) !important; }

      .ct-error { animation: ct-shake 0.45s cubic-bezier(.22,1,.36,1) forwards; }
    `;
    document.head.appendChild(s);
  }, []);
}

/* ─── iOS Spring physics ─────────────────────────────────────────── */
function useSpring(target, cfg = {}) {
  const K = cfg.K || 120, D = cfg.D || 18;
  const s = useRef({ pos: target, vel: 0, raf: null });
  const [v, setV] = useState(target);
  useEffect(() => {
    const st = s.current;
    const tick = () => {
      st.vel += (-K * (st.pos - target) - D * st.vel) / 60;
      st.pos += st.vel / 60;
      if (Math.abs(st.pos - target) < 0.01 && Math.abs(st.vel) < 0.01) {
        st.pos = target; st.vel = 0; setV(target); return;
      }
      setV(st.pos);
      st.raf = requestAnimationFrame(tick);
    };
    cancelAnimationFrame(st.raf);
    st.raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(st.raf);
  }, [target, K, D]);
  return v;
}

/* ─── useInView ──────────────────────────────────────────────────── */
function useInView(threshold = 0.1) {
  const ref = useRef(null);
  const [inView, setInView] = useState(false);
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const obs = new IntersectionObserver(
      ([e]) => { if (e.isIntersecting) { setInView(true); obs.unobserve(el); } },
      { threshold }
    );
    obs.observe(el);
    return () => obs.disconnect();
  }, [threshold]);
  return [ref, inView];
}

/* ─── Animated map block ─────────────────────────────────────────── */
function MapBlock({ address, inView, delay }) {
  const [mounted, setMounted] = useState(false);
  useEffect(() => { if (inView) setTimeout(() => setMounted(true), delay); }, [inView, delay]);

  return (
    <div style={{
      marginTop:6, borderRadius:12, overflow:'hidden',
      border:'1px solid rgba(0,67,114,0.08)',
      background:'linear-gradient(135deg, rgba(0,67,114,0.03), rgba(0,86,154,0.015))',
      height:164, display:'flex', alignItems:'center', justifyContent:'center',
      position:'relative',
      opacity:0,
      ...(inView && { animation:`ct-scaleIn 0.55s cubic-bezier(.22,1,.36,1) ${delay}ms forwards` }),
    }}>
      {/* Grid lines */}
      <svg width="100%" height="100%" style={{ position:'absolute', inset:0 }}>
        {[1,2,3,4,5].map(i => (
          <line key={`h${i}`} x1="0" y1={`${i*100/6}%`} x2="100%" y2={`${i*100/6}%`}
            stroke="rgba(0,67,114,0.06)" strokeWidth="1"/>
        ))}
        {[1,2,3,4,5,6,7].map(i => (
          <line key={`v${i}`} x1={`${i*100/8}%`} y1="0" x2={`${i*100/8}%`} y2="100%"
            stroke="rgba(0,67,114,0.06)" strokeWidth="1"/>
        ))}
      </svg>

      {/* Radar rings — animate in after mount */}
      <svg width="100%" height="100%" style={{ position:'absolute', inset:0, overflow:'visible' }}>
        <defs>
          <radialGradient id="ct-rg">
            <stop offset="0%"   stopColor="rgba(0,67,114,0.18)"/>
            <stop offset="100%" stopColor="rgba(0,67,114,0)"/>
          </radialGradient>
        </defs>
        {mounted && [0, 1, 2].map(i => (
          <circle key={i} cx="50%" cy="50%"
            r={16 + i * 18}
            fill="none"
            stroke="rgba(0,67,114,0.1)"
            strokeWidth="1"
            style={{
              opacity:0,
              animation:`ct-scaleIn 0.5s cubic-bezier(.22,1,.36,1) ${i * 120}ms forwards`,
              transformOrigin:'50% 50%',
            }}
          />
        ))}
        {/* Ping pulse */}
        {mounted && (
          <>
            <circle cx="50%" cy="50%" r="7"
              fill="rgba(0,67,114,0.12)"
              style={{ animation:'ct-ping 1.8s ease-out infinite' }}
            />
            <circle cx="50%" cy="50%" r="7"
              fill="rgba(0,67,114,0.12)"
              style={{ animation:'ct-ping 1.8s ease-out 0.6s infinite' }}
            />
          </>
        )}
        {/* Center dot */}
        {mounted && (
          <circle cx="50%" cy="50%" r="5"
            fill="#004372" opacity="0.35"
            style={{ opacity:0, animation:'ct-fadeIn 0.4s ease 0.3s forwards' }}
          />
        )}
      </svg>

      <div style={{ position:'relative', zIndex:1, textAlign:'center' }}>
        <MapPin size={18} strokeWidth={1.5}
          style={{ color:'rgba(0,67,114,0.32)', marginBottom:5,
            opacity:0,
            ...(mounted && { animation:'ct-fadeUp 0.4s ease 0.25s forwards' }),
          }}
        />
        <p style={{
          fontSize:11.5, color:'rgba(0,67,114,0.38)', margin:0,
          fontFamily:"'Inter', system-ui, sans-serif", fontWeight:500,
          opacity:0,
          ...(mounted && { animation:'ct-fadeIn 0.4s ease 0.4s forwards' }),
        }}>
          {address || 'Москва, Пречистенская набережная, 11'}
        </p>
      </div>
    </div>
  );
}

/* ─── Contact card ───────────────────────────────────────────────── */
function ContactCard({ icon: Icon, label, value, href, index, inView }) {
  const Tag = href ? 'a' : 'div';
  return (
    <Tag
      href={href || undefined}
      className="ct-card"
      style={{
        display:'flex', alignItems:'center', gap:16,
        padding:'17px 22px',
        background:'#fff',
        borderRadius:12,
        border:'1px solid rgba(0,67,114,0.08)',
        boxShadow:'0 1px 4px rgba(0,0,0,0.04), 0 4px 16px rgba(0,67,114,0.04)',
        textDecoration:'none', cursor: href ? 'pointer' : 'default',
        opacity:0,
        ...(inView && { animation:`ct-slideR 0.52s cubic-bezier(.22,1,.36,1) ${index * 80}ms forwards` }),
      }}
    >
      <div className="ct-icon-badge" style={{
        width:42, height:42, borderRadius:10, flexShrink:0,
        background:'linear-gradient(135deg, rgba(0,67,114,0.07), rgba(0,86,154,0.04))',
        border:'1px solid rgba(0,67,114,0.09)',
        display:'flex', alignItems:'center', justifyContent:'center',
        transition:'background 0.25s ease',
      }}>
        <Icon size={17} strokeWidth={1.8} style={{ color:'#004372' }}/>
      </div>

      <div style={{ flex:1, minWidth:0 }}>
        <p style={{
          fontSize:10, fontWeight:700, letterSpacing:'0.12em',
          textTransform:'uppercase', color:'rgba(0,67,114,0.4)',
          margin:'0 0 2px', fontFamily:"'Inter', system-ui, sans-serif",
        }}>{label}</p>
        <p style={{
          fontSize:14, fontWeight:500, color:'#1e293b', margin:0, lineHeight:1.4,
          fontFamily:"'Inter', system-ui, sans-serif",
          overflow:'hidden', textOverflow:'ellipsis', whiteSpace:'nowrap',
        }}>{value}</p>
      </div>

      {href && (
        <ArrowRight size={13} strokeWidth={2}
          className="ct-arrow"
          style={{ color:'rgba(0,67,114,0.25)', flexShrink:0, transition:'color 0.2s ease' }}
        />
      )}
    </Tag>
  );
}

/* ─── Animated Field — label floats, border draws ───────────────── */
function Field({ label, children, inView, delay = 0 }) {
  return (
    <div style={{
      display:'flex', flexDirection:'column', gap:5,
      opacity:0,
      ...(inView && { animation:`ct-fadeUp 0.45s cubic-bezier(.22,1,.36,1) ${delay}ms forwards` }),
    }}>
      <label style={{
        fontSize:10.5, fontWeight:700, letterSpacing:'0.1em',
        textTransform:'uppercase', color:'rgba(0,67,114,0.45)',
        fontFamily:"'Inter', system-ui, sans-serif",
        transition:'color 0.2s ease',
      }}>{label}</label>
      {children}
    </div>
  );
}

const inputBase = {
  width:'100%', padding:'11px 13px',
  background:'rgba(0,67,114,0.018)',
  border:'1.5px solid rgba(0,67,114,0.1)',
  borderRadius:8, fontSize:13.5, color:'#1e293b',
  fontFamily:"'Inter', system-ui, sans-serif",
  boxSizing:'border-box',
};

/* ─── Success state ──────────────────────────────────────────────── */
function SuccessState({ onReset }) {
  return (
    <div style={{ padding:'40px 16px', textAlign:'center', animation:'ct-fadeIn 0.5s ease forwards' }}>
      {/* Animated rings behind icon */}
      <div style={{ position:'relative', display:'inline-block', marginBottom:16 }}>
        {[0, 1].map(i => (
          <div key={i} style={{
            position:'absolute', inset:-8,
            borderRadius:'50%',
            border:'1.5px solid rgba(0,67,114,0.2)',
            animation:`ct-ringOut 1s ease ${i * 0.18}s forwards`,
          }}/>
        ))}
        <div style={{
          width:56, height:56, borderRadius:'50%',
          background:'rgba(0,67,114,0.06)',
          border:'1.5px solid rgba(0,67,114,0.14)',
          display:'flex', alignItems:'center', justifyContent:'center',
          animation:'ct-checkPop 0.55s cubic-bezier(.22,1,.36,1) forwards',
          position:'relative', zIndex:1,
        }}>
          <CheckCircle size={24} strokeWidth={1.8} style={{ color:'#004372' }}/>
        </div>
      </div>

      <p style={{
        fontSize:15, fontWeight:600, color:'#1e293b', margin:'0 0 5px',
        fontFamily:"'Inter', system-ui, sans-serif",
        opacity:0, animation:'ct-fadeUp 0.4s ease 0.2s forwards',
      }}>
        Сообщение отправлено
      </p>
      <p style={{
        fontSize:13, color:'#94a3b8', margin:'0 0 22px',
        fontFamily:"'Inter', system-ui, sans-serif",
        opacity:0, animation:'ct-fadeUp 0.4s ease 0.32s forwards',
      }}>
        Мы свяжемся с вами в ближайшее время
      </p>
      <button onClick={onReset} style={{
        fontSize:12.5, color:'#004372', background:'none', border:'none',
        cursor:'pointer', textDecoration:'underline', textDecorationStyle:'dotted',
        fontFamily:"'Inter', system-ui, sans-serif",
        opacity:0, animation:'ct-fadeIn 0.4s ease 0.45s forwards',
        transition:'opacity 0.2s ease',
      }}>
        Отправить ещё одно
      </button>
    </div>
  );
}

/* ─── Main ───────────────────────────────────────────────────────── */
const ContactsSection = ({ contacts = {}, loading = false }) => {
  useContactsKeyframes();

  const [headerRef, headerInView] = useInView(0.1);
  const [cardsRef,  cardsInView]  = useInView(0.08);
  const [formRef,   formInView]   = useInView(0.08);

  const [formData,     setFormData]     = useState({ name:'', email:'', phone:'', message:'' });
  const [submitting,   setSubmitting]   = useState(false);
  const [submitStatus, setSubmitStatus] = useState(null);
  const [hasError,     setHasError]     = useState(false);

  // Spring-animated form card elevation on formInView
  const formElevation = useSpring(formInView ? 1 : 0, { K: 80, D: 18 });

  const handleChange = e => {
    const { name, value } = e.target;
    setFormData(p => ({ ...p, [name]: value }));
  };

  const handleSubmit = async e => {
    e.preventDefault();
    setSubmitting(true);
    setSubmitStatus(null);
    setHasError(false);
    try {
      const { error } = await supabase.from('inquiries').insert([{
        name: formData.name, email: formData.email,
        phone: formData.phone, message: formData.message,
        created_at: new Date().toISOString(),
      }]);
      if (error) throw error;
      setSubmitStatus('success');
      setFormData({ name:'', email:'', phone:'', message:'' });
    } catch {
      setSubmitStatus('error');
      setHasError(true);
      setTimeout(() => setHasError(false), 500);
    } finally {
      setSubmitting(false);
    }
  };

  const cards = [
    contacts?.address       && { icon:MapPin, label:'Адрес',        value:contacts.address,       href:null },
    contacts?.phone         && { icon:Phone,  label:'Телефон',      value:contacts.phone,         href:`tel:${contacts.phone}` },
    contacts?.email         && { icon:Mail,   label:'Email',        value:contacts.email,         href:`mailto:${contacts.email}` },
    contacts?.working_hours && { icon:Clock,  label:'Время работы', value:contacts.working_hours, href:null },
  ].filter(Boolean);

  if (loading) return (
    <section id="contacts" style={{ padding:'100px 0', background:'#f8f9fb', textAlign:'center' }}>
      <div style={{ display:'inline-flex', alignItems:'center', gap:10 }}>
        <div style={{ width:16, height:16, borderRadius:'50%', border:'2px solid rgba(0,67,114,0.12)', borderTopColor:'#004372', animation:'ct-spin 0.8s linear infinite' }}/>
        <span style={{ fontSize:14, color:'#94a3b8', fontFamily:"'Inter', system-ui, sans-serif" }}>Загрузка...</span>
      </div>
    </section>
  );

  return (
    <section id="contacts" style={{ padding:'100px 0 120px', background:'#f8f9fb', position:'relative' }}>
      <div style={{ position:'absolute', top:0, left:0, right:0, height:'1px', background:'rgba(0,67,114,0.08)' }}/>

      <div style={{ maxWidth:1100, margin:'0 auto', padding:'0 40px' }}>

        {/* ── Header ── */}
        <div ref={headerRef} style={{ marginBottom:52 }}>

          {/* Eyebrow line */}
          <div style={{
            display:'flex', alignItems:'center', gap:10, marginBottom:16,
            opacity:0, ...(headerInView && { animation:'ct-fadeIn 0.5s ease forwards' }),
          }}>
            <div style={{
              width:24, height:2, borderRadius:1,
              background:'linear-gradient(90deg, #004372, #00569a)',
              transformOrigin:'left',
              transform: headerInView ? 'scaleX(1)' : 'scaleX(0)',
              transition:'transform 0.65s cubic-bezier(.22,1,.36,1) 0.1s',
            }}/>
            <span style={{
              fontSize:11, fontWeight:700, letterSpacing:'0.14em',
              textTransform:'uppercase', color:'#004372',
              fontFamily:"'Inter', system-ui, sans-serif",
            }}>
              Свяжитесь с нами
            </span>
          </div>

          {/* Big title */}
          <div style={{ opacity:0, ...(headerInView && { animation:'ct-fadeUp 0.65s cubic-bezier(.22,1,.36,1) 80ms forwards' }) }}>
            <h2 style={{
              fontFamily:"'Playfair Display', Georgia, serif",
              fontSize:'clamp(44px, 7vw, 88px)',
              fontWeight:900, lineHeight:0.95,
              color:'#0f172a', letterSpacing:'-0.03em', margin:0,
            }}>
              Контакты
            </h2>
          </div>

          {/* Divider + subtitle */}
          <div style={{
            marginTop:18, paddingTop:18,
            borderTop:'1px solid rgba(0,0,0,0.08)',
            opacity:0, ...(headerInView && { animation:'ct-fadeUp 0.55s cubic-bezier(.22,1,.36,1) 200ms forwards' }),
          }}>
            <p style={{
              fontSize:14.5, color:'#64748b', margin:0, lineHeight:1.6,
              fontFamily:"'Inter', system-ui, sans-serif", maxWidth:480,
            }}>
              Получите консультацию от специалистов института
            </p>
          </div>
        </div>

        {/* ── Two-column grid ── */}
        <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr', gap:32, alignItems:'start' }}>

          {/* Left — cards + animated map */}
          <div ref={cardsRef} style={{ display:'flex', flexDirection:'column', gap:10 }}>
            {cards.map((c, i) => (
              <ContactCard key={i} {...c} index={i} inView={cardsInView}/>
            ))}
            <MapBlock
              address={contacts?.address}
              inView={cardsInView}
              delay={cards.length * 80 + 60}
            />
          </div>

          {/* Right — form, spring-elevated shadow */}
          <div
            ref={formRef}
            style={{
              background:'#fff',
              borderRadius:16,
              border:'1px solid rgba(0,67,114,0.09)',
              boxShadow:`0 1px 4px rgba(0,0,0,0.04), 0 ${8 + formElevation * 16}px ${32 + formElevation * 24}px rgba(0,67,114,${0.03 + formElevation * 0.06})`,
              padding:'32px 28px',
              opacity:0,
              transition:'box-shadow 0.1s linear',
              ...(formInView && { animation:'ct-slideL 0.62s cubic-bezier(.22,1,.36,1) 100ms forwards' }),
            }}
          >
            {/* Form header */}
            <div style={{
              marginBottom:24, paddingBottom:18,
              borderBottom:'1px solid rgba(0,67,114,0.07)',
            }}>
              <h3 style={{
                fontFamily:"'Playfair Display', Georgia, serif",
                fontSize:22, fontWeight:700, color:'#0f172a',
                margin:'0 0 3px', letterSpacing:'-0.02em',
              }}>
                Напишите нам
              </h3>
              <p style={{ fontSize:12.5, color:'#94a3b8', margin:0, fontFamily:"'Inter', system-ui, sans-serif" }}>
                Ответим в течение одного рабочего дня
              </p>
            </div>

            {/* Success */}
            {submitStatus === 'success'
              ? <SuccessState onReset={() => setSubmitStatus(null)}/>
              : (
              <form onSubmit={handleSubmit} style={{ display:'flex', flexDirection:'column', gap:16 }}>

                {/* Error banner */}
                {submitStatus === 'error' && (
                  <div className={hasError ? 'ct-error' : ''} style={{
                    display:'flex', alignItems:'center', gap:9,
                    padding:'11px 14px', borderRadius:8,
                    background:'rgba(239,68,68,0.05)',
                    border:'1px solid rgba(239,68,68,0.14)',
                    animation:'ct-fadeIn 0.3s ease forwards',
                  }}>
                    <AlertCircle size={14} strokeWidth={2} style={{ color:'#ef4444', flexShrink:0 }}/>
                    <span style={{ fontSize:13, color:'#dc2626', fontFamily:"'Inter', system-ui, sans-serif" }}>
                      Ошибка отправки. Попробуйте позже.
                    </span>
                  </div>
                )}

                {/* Name + Email */}
                <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr', gap:12 }}>
                  <Field label="Имя *" inView={formInView} delay={180}>
                    <input className="ct-input" type="text" name="name"
                      placeholder="Иван Иванов" value={formData.name}
                      onChange={handleChange} required style={inputBase}/>
                  </Field>
                  <Field label="Email *" inView={formInView} delay={220}>
                    <input className="ct-input" type="email" name="email"
                      placeholder="ivan@mail.ru" value={formData.email}
                      onChange={handleChange} required style={inputBase}/>
                  </Field>
                </div>

                <Field label="Телефон" inView={formInView} delay={260}>
                  <input className="ct-input" type="tel" name="phone"
                    placeholder="+7 (999) 000-00-00" value={formData.phone}
                    onChange={handleChange} style={inputBase}/>
                </Field>

                <Field label="Сообщение *" inView={formInView} delay={300}>
                  <textarea className="ct-input" name="message" rows={4}
                    placeholder="Расскажите о вашем вопросе..."
                    value={formData.message} onChange={handleChange} required
                    style={{ ...inputBase, resize:'none' }}/>
                </Field>

                {/* Submit */}
                <div style={{
                  opacity:0,
                  ...(formInView && { animation:'ct-fadeUp 0.45s cubic-bezier(.22,1,.36,1) 340ms forwards' }),
                }}>
                  <button type="submit" disabled={submitting} className="ct-submit" style={{
                    width:'100%',
                    display:'flex', alignItems:'center', justifyContent:'center', gap:8,
                    padding:'13px 24px', borderRadius:8,
                    background: submitting ? 'rgba(0,67,114,0.45)' : '#004372',
                    color:'#fff', border:'none',
                    cursor: submitting ? 'default' : 'pointer',
                    fontSize:13.5, fontWeight:600,
                    fontFamily:"'Inter', system-ui, sans-serif",
                    letterSpacing:'0.02em',
                  }}>
                    {submitting ? (
                      <>
                        <div style={{ width:13, height:13, borderRadius:'50%', border:'2px solid rgba(255,255,255,0.25)', borderTopColor:'#fff', animation:'ct-spin 0.7s linear infinite' }}/>
                        Отправка...
                      </>
                    ) : (
                      <><Send size={13} strokeWidth={2}/> Отправить сообщение</>
                    )}
                  </button>
                </div>

                <p style={{
                  fontSize:11, color:'#cbd5e1', margin:0, textAlign:'center',
                  fontFamily:"'Inter', system-ui, sans-serif",
                  opacity:0,
                  ...(formInView && { animation:'ct-fadeIn 0.4s ease 420ms forwards' }),
                }}>
                  Нажимая кнопку, вы соглашаетесь с политикой конфиденциальности
                </p>

              </form>
            )}
          </div>
        </div>
      </div>
    </section>
  );
};

export default ContactsSection;