import React, { useState, useEffect, createContext, useContext } from 'react';
import { RouterProvider } from 'react-router-dom';
import { getUniversityInfo, getContacts } from './services/supabaseClient';
import router from './router';
import './App.css';

// Global data context so all pages can access Supabase data without re-fetching
export const AppDataContext = createContext({});
export const useAppData = () => useContext(AppDataContext);

function App() {
  const [universityData, setUniversityData] = useState({});
  const [contactsData, setContactsData]     = useState({});
  const [loading, setLoading]               = useState(true);

  useEffect(() => {
    const fetchData = async () => {
      const [univData, contactData] = await Promise.all([
        getUniversityInfo(),
        getContacts(),
      ]);
      setUniversityData(univData);
      setContactsData(contactData);
      setLoading(false);
    };
    fetchData();
  }, []);

  return (
    <AppDataContext.Provider value={{ universityData, contactsData, loading }}>
      <RouterProvider router={router} />
    </AppDataContext.Provider>
  );
}

export default App;
