/**
 * Получить сведения об университете
 */
export const getUniversityInfo = async () => {
  try {
    const { data, error } = await supabase
      .from('university_info')
      .select('*')
      .single();

    if (error && error.code !== 'PGRST116') throw error;
    return data || {};
  } catch (error) {
    console.error('Ошибка при загрузке информации об университете:', error);
    return {};
  }
};

