/**
 * Получить документы для библиотеки.
 *
 * file_url в БД хранить как путь внутри бакета:
 *   "program-documents/WorkFile.docx"
 *
 * Функция автоматически строит публичный URL:
 *   https://<project>.supabase.co/storage/v1/object/public/program-documents/WorkFile.docx
 *
 * Если file_url уже начинается с "http" — оставляется без изменений.
 */
export const getDocuments = async () => {
  try {
    const { data, error } = await supabase
      .from('documents')
      .select('id, title, category, file_url, external_link, created_at')
      .eq('published', true)
      .order('created_at', { ascending: false });

    if (error) throw error;

    const docs = (data || []).map(doc => {
      if (!doc.file_url)                    return doc;
      if (doc.file_url.startsWith('http')) return doc;

      // "program-documents/WorkFile.docx" → bucket + path
      const idx = doc.file_url.indexOf('/');
      if (idx === -1)                       return doc;

      const bucket   = doc.file_url.slice(0, idx);
      const filePath = doc.file_url.slice(idx + 1);

      const { data: urlData } = supabase.storage
        .from(bucket)
        .getPublicUrl(filePath);

      return { ...doc, file_url: urlData?.publicUrl ?? doc.file_url };
    });

    return docs;
  } catch (error) {
    console.error('Ошибка при загрузке документов:', error);
    return [];
  }
};