import React, { useState, useEffect, useRef } from 'react';
import { FileText, Download, Clock, Users, ChevronDown } from 'lucide-react';
import { getPrograms } from '../services/supabaseClient';

/* ─── Keyframes ──────────────────────────────────────────────────── */
function useProgramsKeyframes() {
  useEffect(() => {
    const id = 'programs-keyframes';
    if (document.getElementById(id)) return;
    const style = document.createElement('style');
    style.id = id;
    style.textContent = `
      @keyframes pg-fadeUp {
        from { opacity: 0; transform: translateY(32px); }
        to   { opacity: 1; transform: translateY(0); }
      }
      @keyframes pg-fadeIn {
        from { opacity: 0; }
        to   { opacity: 1; }
      }
      @keyframes pg-scaleIn {
        from { opacity: 0; transform: scale(0.94) translateY(20px); }
        to   { opacity: 1; transform: scale(1) translateY(0); }
      }
      @keyframes pg-slideDown {
        from { opacity: 0; transform: translateY(-8px); }
        to   { opacity: 1; transform: translateY(0); }
      }
      @keyframes pg-spin {
        to { transform: rotate(360deg); }
      }
    `;
    document.head.appendChild(style);
  }, []);
}

/* ─── IntersectionObserver hook ──────────────────────────────────── */
function useInView(threshold = 0.12) {
  const ref = useRef(null);
  const [inView, setInView] = useState(false);
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const obs = new IntersectionObserver(
      ([e]) => { if (e.isIntersecting) { setInView(true); obs.unobserve(el); } },
      { threshold }
    );
    obs.observe(el);
    return () => obs.disconnect();
  }, [threshold]);
  return [ref, inView];
}

/* ─── Program Card ───────────────────────────────────────────────── */
function ProgramCard({ program, index }) {
  const [cardRef, inView] = useInView(0.08);
  const [expanded, setExpanded] = useState(false);
  const [hovered, setHovered] = useState(false);
  const [btnHovered, setBtnHovered] = useState(false);

  return (
    <div
      ref={cardRef}
      onMouseEnter={() => setHovered(true)}
      onMouseLeave={() => setHovered(false)}
      style={{
        opacity: 0,
        ...(inView && {
          animation: `pg-scaleIn 0.6s cubic-bezier(.22,1,.36,1) ${index * 80}ms forwards`,
        }),
        borderRadius: 24,
        background: '#ffffff',
        border: '1px solid',
        borderColor: hovered ? 'rgba(0,67,114,0.2)' : 'rgba(0,0,0,0.07)',
        boxShadow: hovered
          ? '0 20px 60px rgba(0,67,114,0.12), 0 4px 16px rgba(0,67,114,0.08)'
          : '0 2px 16px rgba(0,0,0,0.05)',
        transition: 'box-shadow 0.35s ease, border-color 0.35s ease, transform 0.35s ease',
        transform: hovered ? 'translateY(-4px)' : 'translateY(0)',
        overflow: 'hidden',
        display: 'flex',
        flexDirection: 'column',
      }}
    >
      {/* Header */}
      <div style={{
        background: 'linear-gradient(135deg, #004372 0%, #00569a 100%)',
        padding: '28px 28px 24px',
        position: 'relative',
        overflow: 'hidden',
      }}>
        <div style={{
          position: 'absolute', inset: 0,
          background: 'linear-gradient(105deg, transparent 40%, rgba(255,255,255,0.05) 50%, transparent 60%)',
          backgroundSize: '400px 100%',
          pointerEvents: 'none',
        }} />
        <div style={{
          position: 'absolute', top: -20, right: -20,
          width: 100, height: 100, borderRadius: '50%',
          background: 'rgba(255,255,255,0.05)',
          pointerEvents: 'none',
        }} />
        <h3 style={{
          fontSize: 18, fontWeight: 700, color: '#fff',
          lineHeight: 1.35, marginBottom: program.duration ? 10 : 0,
          position: 'relative', zIndex: 1,
        }}>
          {program.title}
        </h3>
        {program.duration && (
          <div style={{
            display: 'flex', alignItems: 'center', gap: 6,
            color: 'rgba(255,255,255,0.7)', fontSize: 13,
            position: 'relative', zIndex: 1,
          }}>
            <Clock size={13} strokeWidth={2} />
            <span>{program.duration}</span>
          </div>
        )}
      </div>

      {/* Body */}
      <div style={{ padding: '24px 28px', flex: 1 }}>
        <p style={{
          fontSize: 14, color: '#4b5563', lineHeight: 1.7,
          display: '-webkit-box', WebkitLineClamp: 3,
          WebkitBoxOrient: 'vertical', overflow: 'hidden',
          marginBottom: program.student_limit ? 16 : 0,
        }}>
          {program.description || 'Описание программы'}
        </p>

        {program.student_limit && (
          <div style={{
            display: 'inline-flex', alignItems: 'center', gap: 6,
            background: 'rgba(0,67,114,0.06)', color: '#004372',
            padding: '5px 12px', borderRadius: 99, fontSize: 12.5,
            fontWeight: 600,
          }}>
            <Users size={13} strokeWidth={2} />
            <span>Мест: {program.student_limit}</span>
          </div>
        )}

        {/* Files accordion */}
        {program.files && program.files.length > 0 && (
          <div style={{ marginTop: 20, paddingTop: 20, borderTop: '1px solid rgba(0,0,0,0.06)' }}>
            <button
              onClick={() => setExpanded(v => !v)}
              style={{
                display: 'flex', alignItems: 'center', justifyContent: 'space-between',
                width: '100%', background: 'none', border: 'none', cursor: 'pointer',
                padding: 0, color: '#004372', fontSize: 13.5, fontWeight: 600,
              }}
            >
              <span style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
                <FileText size={14} strokeWidth={2} />
                Материалы ({program.files.length})
              </span>
              <ChevronDown
                size={15} strokeWidth={2.5}
                style={{
                  transition: 'transform 0.3s cubic-bezier(.22,1,.36,1)',
                  transform: expanded ? 'rotate(180deg)' : 'rotate(0deg)',
                }}
              />
            </button>

            {expanded && (
              <div style={{
                marginTop: 12, display: 'flex', flexDirection: 'column', gap: 6,
                animation: 'pg-slideDown 0.3s cubic-bezier(.22,1,.36,1) forwards',
              }}>
                {program.files.map((file) => (
                  <a
                    key={file.id}
                    href={file.file_url}
                    target="_blank"
                    rel="noopener noreferrer"
                    style={{ textDecoration: 'none' }}
                  >
                    <div
                      style={{
                        display: 'flex', alignItems: 'center', gap: 10,
                        padding: '10px 12px', borderRadius: 12,
                        background: 'rgba(0,67,114,0.04)',
                        border: '1px solid rgba(0,67,114,0.08)',
                        transition: 'background 0.2s ease, border-color 0.2s ease',
                      }}
                      onMouseEnter={e => {
                        e.currentTarget.style.background = 'rgba(0,67,114,0.09)';
                        e.currentTarget.style.borderColor = 'rgba(0,67,114,0.2)';
                      }}
                      onMouseLeave={e => {
                        e.currentTarget.style.background = 'rgba(0,67,114,0.04)';
                        e.currentTarget.style.borderColor = 'rgba(0,67,114,0.08)';
                      }}
                    >
                      <FileText size={14} style={{ color: '#004372', flexShrink: 0 }} />
                      <span style={{
                        flex: 1, fontSize: 13, color: '#1f2937', fontWeight: 500,
                        overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap',
                      }}>
                        {file.file_name}
                      </span>
                      <Download size={13} style={{ color: '#004372', flexShrink: 0 }} />
                    </div>
                  </a>
                ))}
              </div>
            )}
          </div>
        )}
      </div>

      {/* Footer CTA */}
      <div style={{ padding: '0 28px 24px' }}>
        <button
          onMouseEnter={() => setBtnHovered(true)}
          onMouseLeave={() => setBtnHovered(false)}
          style={{
            width: '100%',
            background: btnHovered
              ? 'linear-gradient(135deg, #004372, #00569a)'
              : 'rgba(0,67,114,0.07)',
            color: btnHovered ? '#fff' : '#004372',
            border: '1.5px solid',
            borderColor: btnHovered ? 'transparent' : 'rgba(0,67,114,0.2)',
            padding: '11px 0', borderRadius: 12,
            fontSize: 14, fontWeight: 700,
            cursor: 'pointer', letterSpacing: '0.01em',
            transition: 'all 0.3s ease',
          }}
        >
          Подать заявку
        </button>
      </div>
    </div>
  );
}

/* ─── Main Section ───────────────────────────────────────────────── */
const ProgramsSection = () => {
  useProgramsKeyframes();
  const [headerRef, headerInView] = useInView(0.2);
  const [programs, setPrograms] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    getPrograms().then(data => {
      setPrograms(data);
      setLoading(false);
    });
  }, []);

  return (
    <section
      id="programs"
      style={{
        padding: '112px 24px',
        background: 'linear-gradient(180deg, #ffffff 0%, #f5f7ff 100%)',
        position: 'relative',
        overflow: 'hidden',
      }}
    >
      {/* Background grid */}
      <div style={{
        position: 'absolute', inset: 0, pointerEvents: 'none',
        backgroundImage: `
          linear-gradient(rgba(0,67,114,0.03) 1px, transparent 1px),
          linear-gradient(90deg, rgba(0,67,114,0.03) 1px, transparent 1px)
        `,
        backgroundSize: '48px 48px',
      }} />

      {/* Glow */}
      <div style={{
        position: 'absolute', top: -80, right: -80,
        width: 400, height: 400, borderRadius: '50%',
        background: 'radial-gradient(circle, rgba(0,86,154,0.07) 0%, transparent 70%)',
        pointerEvents: 'none',
      }} />

      <div style={{ maxWidth: 1280, margin: '0 auto', position: 'relative', zIndex: 1 }}>

        {/* Header */}
        <div ref={headerRef} style={{ textAlign: 'center', marginBottom: 72 }}>

          <div style={{ opacity: 0, ...(headerInView && { animation: 'pg-fadeIn 0.5s cubic-bezier(.22,1,.36,1) forwards' }) }}>
            <span style={{
              display: 'inline-block',
              background: 'rgba(0,67,114,0.08)', color: '#004372',
              border: '1px solid rgba(0,67,114,0.15)',
              padding: '6px 18px', borderRadius: 99,
              fontSize: 12.5, fontWeight: 700,
              letterSpacing: '0.06em', textTransform: 'uppercase',
              marginBottom: 20,
            }}>
              Обучение
            </span>
          </div>

          <div style={{ opacity: 0, ...(headerInView && { animation: 'pg-fadeUp 0.65s cubic-bezier(.22,1,.36,1) 120ms forwards' }) }}>
            <h2 style={{
              fontSize: 'clamp(32px, 5vw, 52px)',
              fontWeight: 800, color: '#0f172a',
              letterSpacing: '-0.02em', lineHeight: 1.15, marginBottom: 20,
            }}>
              Образовательные программы
            </h2>
          </div>

          <div style={{ opacity: 0, ...(headerInView && { animation: 'pg-fadeUp 0.65s cubic-bezier(.22,1,.36,1) 240ms forwards' }) }}>
            <p style={{
              fontSize: 18, color: '#64748b',
              lineHeight: 1.7, maxWidth: 520, margin: '0 auto 28px',
            }}>
              Выберите программу обучения, которая соответствует вашим целям и амбициям
            </p>
          </div>

          {/* Accent line */}
          <div style={{
            height: 3, width: 56, borderRadius: 2,
            background: 'linear-gradient(90deg, #004372, #00569a)',
            margin: '0 auto',
            transformOrigin: 'center',
            transform: headerInView ? 'scaleX(1)' : 'scaleX(0)',
            transition: 'transform 0.7s cubic-bezier(.22,1,.36,1) 350ms',
          }} />
        </div>

        {/* Loading */}
        {loading && (
          <div style={{ textAlign: 'center', padding: '48px 0' }}>
            <div style={{ display: 'inline-flex', gap: 10, alignItems: 'center', color: '#64748b', fontSize: 15 }}>
              <div style={{
                width: 18, height: 18, borderRadius: '50%',
                border: '2px solid rgba(0,67,114,0.15)',
                borderTopColor: '#004372',
                animation: 'pg-spin 0.8s linear infinite',
              }} />
              Загрузка программ...
            </div>
          </div>
        )}

        {/* Empty */}
        {!loading && programs.length === 0 && (
          <div style={{
            textAlign: 'center', padding: '48px 32px',
            background: 'rgba(0,67,114,0.04)', borderRadius: 20,
            border: '1px solid rgba(0,67,114,0.1)',
            animation: 'pg-fadeIn 0.5s ease forwards',
          }}>
            <p style={{ color: '#64748b', fontSize: 15 }}>
              Программы ещё не добавлены администратором
            </p>
          </div>
        )}

        {/* Cards */}
        {!loading && programs.length > 0 && (
          <div style={{
            display: 'grid',
            gridTemplateColumns: 'repeat(auto-fill, minmax(300px, 1fr))',
            gap: 28,
          }}>
            {programs.map((program, index) => (
              <ProgramCard key={program.id} program={program} index={index} />
            ))}
          </div>
        )}

      </div>
    </section>
  );
};

export default ProgramsSection;