import React, { useState, useEffect, useRef } from 'react';
import { Mail, Phone } from 'lucide-react';
import { getStaff } from '../services/supabaseClient';

/* ─── Keyframes ──────────────────────────────────────────────────── */
function useLeadershipKeyframes() {
  useEffect(() => {
    const id = 'leadership-keyframes';
    if (document.getElementById(id)) return;
    const style = document.createElement('style');
    style.id = id;
    style.textContent = `
      @import url('https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,700;1,400;1,700&display=swap');

      @keyframes ls-fadeUp {
        from { opacity: 0; transform: translateY(36px); }
        to   { opacity: 1; transform: translateY(0); }
      }
      @keyframes ls-fadeIn {
        from { opacity: 0; }
        to   { opacity: 1; }
      }
      @keyframes ls-slideRight {
        from { opacity: 0; transform: translateX(-32px); }
        to   { opacity: 1; transform: translateX(0); }
      }
      @keyframes ls-scaleIn {
        from { opacity: 0; transform: scale(0.93) translateY(24px); }
        to   { opacity: 1; transform: scale(1) translateY(0); }
      }
      @keyframes ls-spin {
        to { transform: rotate(360deg); }
      }
      @keyframes ls-lineGrow {
        from { width: 0; }
        to   { width: 100%; }
      }
    `;
    document.head.appendChild(style);
  }, []);
}

/* ─── IntersectionObserver hook ──────────────────────────────────── */
function useInView(threshold = 0.1) {
  const ref = useRef(null);
  const [inView, setInView] = useState(false);
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const obs = new IntersectionObserver(
      ([e]) => { if (e.isIntersecting) { setInView(true); obs.unobserve(el); } },
      { threshold }
    );
    obs.observe(el);
    return () => obs.disconnect();
  }, [threshold]);
  return [ref, inView];
}

/* ─── Contact link ───────────────────────────────────────────────── */
function ContactLink({ href, icon: Icon, children }) {
  const [hov, setHov] = useState(false);
  return (
    <a href={href} onMouseEnter={() => setHov(true)} onMouseLeave={() => setHov(false)}
      style={{ textDecoration: 'none', display: 'flex', alignItems: 'center', gap: 9 }}>
      <div style={{
        width: 30, height: 30, borderRadius: 8, flexShrink: 0,
        background: hov ? 'rgba(0,67,114,0.12)' : 'rgba(0,67,114,0.06)',
        display: 'flex', alignItems: 'center', justifyContent: 'center',
        transition: 'background 0.25s ease',
      }}>
        <Icon size={13} strokeWidth={2} style={{ color: '#004372' }} />
      </div>
      <span style={{
        fontSize: 12.5, color: hov ? '#004372' : '#64748b',
        fontWeight: hov ? 600 : 400,
        overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap',
        transition: 'color 0.2s ease',
        transform: hov ? 'translateX(2px)' : 'translateX(0)',
        display: 'inline-block', transition: 'color 0.2s ease, transform 0.2s ease',
      }}>
        {children}
      </span>
    </a>
  );
}

/* ─── FEATURED card (first person — wide) ────────────────────────── */
