/* ─── Animated reveal wrapper ────────────────────────────────────── */
function Reveal({ inView, delay = 0, animation = 'ft-fadeUp', duration = '0.65s', children, style }) {
  return (
    <div style={{
      opacity: 0,
      ...(inView && {
        animation: `${animation} ${duration} cubic-bezier(.22,1,.36,1) ${delay}ms forwards`,
      }),
      ...style,
    }}>
      {children}
    </div>
  );
}

/* ─── Contact row ────────────────────────────────────────────────── */
function ContactRow({ icon: Icon, children, href, type }) {
  const [hovered, setHovered] = useState(false);
  const content = (
    <div
      onMouseEnter={() => setHovered(true)}
      onMouseLeave={() => setHovered(false)}
      style={{
        display: 'flex', alignItems: 'flex-start', gap: 12,
        color: hovered ? 'rgba(255,255,255,1)' : 'rgba(255,255,255,0.65)',
        transition: 'color 0.25s ease',
        cursor: href ? 'pointer' : 'default',
        textDecoration: 'none',
        fontSize: 13.5,
        lineHeight: 1.5,
      }}
    >
      <div style={{
        marginTop: 2, flexShrink: 0,
        opacity: hovered ? 1 : 0.7,
        transition: 'opacity 0.25s ease, transform 0.25s ease',
        transform: hovered ? 'scale(1.15)' : 'scale(1)',
      }}>
        <Icon size={15} strokeWidth={1.8} />
      </div>
      <span>{children}</span>
    </div>
  );
  if (href) return <a href={href} style={{ textDecoration: 'none' }}>{content}</a>;
  return content;
}

/* ─── Social icon button ─────────────────────────────────────────── */
function SocialBtn({ href, icon: Icon, label }) {
  const [hovered, setHovered] = useState(false);
  return (
    <a
      href={href} target="_blank" rel="noopener noreferrer" title={label}
      onMouseEnter={() => setHovered(true)}
      onMouseLeave={() => setHovered(false)}
      style={{
        display: 'flex', alignItems: 'center', justifyContent: 'center',
        width: 36, height: 36, borderRadius: 10,
        background: hovered ? 'rgba(255,255,255,0.18)' : 'rgba(255,255,255,0.08)',
        border: '0.5px solid',
        borderColor: hovered ? 'rgba(255,255,255,0.40)' : 'rgba(255,255,255,0.15)',
        color: hovered ? '#ffffff' : 'rgba(255,255,255,0.65)',
        transition: 'all 0.25s ease',
        transform: hovered ? 'translateY(-2px)' : 'translateY(0)',
        textDecoration: 'none',
        backdropFilter: 'blur(8px)',
        WebkitBackdropFilter: 'blur(8px)',
      }}
    >
      <Icon size={15} strokeWidth={1.8} />
    </a>
  );
}

/* ─── Footer link ────────────────────────────────────────────────── */
function FooterLink({ href, children }) {
  const [hov, setHov] = useState(false);
  return (
    <a
      href={href}
      onMouseEnter={() => setHov(true)}
      onMouseLeave={() => setHov(false)}
      style={{
        fontSize: 12.5,
        color: hov ? 'rgba(255,255,255,0.75)' : 'rgba(255,255,255,0.35)',
        textDecoration: 'none',
        transition: 'color 0.2s ease',
      }}
    >
      {children}
    </a>
  );
}

