import React, { useEffect, useRef, useState } from 'react';
import { ArrowRight } from 'lucide-react';
import { getSlides } from '../services/supabaseClient';

/* ─── Intersection Observer hook ─────────────────────────────────── */
function useInView(options = {}) {
  const ref = useRef(null);
  const [inView, setInView] = useState(false);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setInView(true);
          observer.unobserve(el);
        }
      },
      { threshold: 0.15, ...options }
    );
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  return [ref, inView];
}

/* ─── Animated counter ───────────────────────────────────────────── */
function AnimatedCounter({ target, duration = 1800, start }) {
  const [value, setValue] = useState(0);
  const hasPlus = String(target).includes('+');
  const numeric = parseInt(String(target).replace('+', ''));

  useEffect(() => {
    if (!start) return;
    let startTime = null;
    const step = (timestamp) => {
      if (!startTime) startTime = timestamp;
      const progress = Math.min((timestamp - startTime) / duration, 1);
      const eased = progress === 1 ? 1 : 1 - Math.pow(2, -10 * progress);
      setValue(Math.floor(eased * numeric));
      if (progress < 1) requestAnimationFrame(step);
    };
    requestAnimationFrame(step);
  }, [start, numeric, duration]);

  return <span>{value}{hasPlus ? '+' : ''}</span>;
}

/* ─── Hero Slider ────────────────────────────────────────────────── */
function HeroSlider({ slides }) {
  const [current, setCurrent] = useState(0);
  const [prevIdx, setPrevIdx] = useState(null);
  const [animating, setAnimating] = useState(false);
  const autoRef = useRef(null);
  const count = slides.length;

  const goTo = (idx) => {
    if (animating || idx === current) return;
    setPrevIdx(current);
    setCurrent(idx);
    setAnimating(true);
    setTimeout(() => { setPrevIdx(null); setAnimating(false); }, 700);
  };

  // Auto-advance
  useEffect(() => {
    if (count < 2) return;
    autoRef.current = setInterval(() => {
      setCurrent(prev => {
        const next = (prev + 1) % count;
        setPrevIdx(prev);
        setAnimating(true);
        setTimeout(() => { setPrevIdx(null); setAnimating(false); }, 700);
        return next;
      });
    }, 4000);
    return () => clearInterval(autoRef.current);
  }, [count]);

  // Pause on hover
  const pause  = () => clearInterval(autoRef.current);
  const resume = () => {
    if (count < 2) return;
    autoRef.current = setInterval(() => {
      setCurrent(prev => {
        const next = (prev + 1) % count;
        setPrevIdx(prev);
        setAnimating(true);
        setTimeout(() => { setPrevIdx(null); setAnimating(false); }, 700);
        return next;
      });
    }, 4000);
  };

  return (
    <div
      className="relative bg-gradient-to-br from-primary-500 via-primary-600 to-primary-800 rounded-3xl text-white flex flex-col justify-end h-[420px] shadow-2xl border border-white/10 overflow-hidden"
      onMouseEnter={pause}
      onMouseLeave={resume}
    >
      {/* ── Images ── */}
      {slides.map((slide, i) => {
        const isActive = i === current;
        const isPrev   = i === prevIdx;
        return (
          <div
            key={slide.id}
            style={{
              position: 'absolute', inset: 0,
              backgroundImage: `url(${slide.image_url})`,
              backgroundSize: 'cover',
              backgroundPosition: 'center',
              transition: 'opacity 0.7s cubic-bezier(.22,1,.36,1), transform 0.7s cubic-bezier(.22,1,.36,1)',
              opacity:   isActive ? 1 : isPrev ? 0 : 0,
              transform: isActive ? 'scale(1.00)' : isPrev ? 'scale(1.04)' : 'scale(1.04)',
              zIndex:    isActive ? 1 : isPrev ? 0 : 0,
            }}
          />
        );
      })}

      {/* Dark gradient overlay — preserves text legibility */}
      <div style={{
        position: 'absolute', inset: 0, zIndex: 2,
        background: 'linear-gradient(to top, rgba(10,30,80,0.72) 0%, rgba(10,30,80,0.15) 55%, transparent 100%)',
      }} />

      {/* Shimmer sweep — original effect */}
      <div
        className="absolute inset-0 pointer-events-none"
        style={{
          zIndex: 3,
          background: 'linear-gradient(105deg, transparent 40%, rgba(255,255,255,0.06) 50%, transparent 60%)',
          backgroundSize: '600px 100%',
          animation: 'hero-shimmer 5s linear infinite',
        }}
      />

      {/* Original decorative blurs */}
      <div className="absolute top-8 right-8 w-24 h-24 bg-white/10 rounded-full blur-2xl" style={{ zIndex: 3 }} />
      <div className="absolute bottom-10 left-8 w-40 h-40 bg-white/5 rounded-full blur-3xl"  style={{ zIndex: 3 }} />

      {/* ── Text content ── */}
      <div className="relative z-10" style={{ zIndex: 4, padding: '0 48px 28px' }}>
        {/* Slide title if present */}
        {slides[current]?.title && (
          <p
            key={`title-${current}`}
            className="text-lg font-medium text-primary-100 mb-2"
            style={{ animation: 'hero-fadeUp 0.5s cubic-bezier(.22,1,.36,1) forwards' }}
          >
            {slides[current].title}
          </p>
        )}
        <p className="text-2xl font-semibold mb-3">
          Присоединяйтесь к нам
        </p>
        <p className="text-primary-100 text-lg leading-relaxed">
          Начните свой путь к успешной карьере в государственном управлении и бизнесе
        </p>
      </div>

      {/* ── Dot / progress slider ── */}
      {count > 1 && (
        <div
          className="relative"
          style={{ zIndex: 5, padding: '0 48px 24px', display: 'flex', alignItems: 'center', gap: 8 }}
        >
          {slides.map((_, i) => (
            <button
              key={i}
              onClick={() => goTo(i)}
              style={{
                height: 3,
                width: i === current ? 28 : 12,
                borderRadius: 99,
                background: i === current ? '#ffffff' : 'rgba(255,255,255,0.35)',
                border: 'none', cursor: 'pointer', padding: 0,
                transition: 'width 0.4s cubic-bezier(.22,1,.36,1), background 0.3s ease',
              }}
            />
          ))}
        </div>
      )}
    </div>
  );
}

/* ─── Main component ─────────────────────────────────────────────── */
const HeroSection = ({ data }) => {
  const [sectionRef, inView] = useInView();
  const [slides, setSlides] = useState([]);

  const [showBadge, setShowBadge] = useState(false);
  const [showTitle, setShowTitle] = useState(false);
  const [showDesc,  setShowDesc]  = useState(false);
  const [showBtns,  setShowBtns]  = useState(false);
  const [showStats, setShowStats] = useState(false);
  const [showCard,  setShowCard]  = useState(false);

  // Fetch slides
  useEffect(() => {
    getSlides().then(setSlides);
  }, []);

  useEffect(() => {
    if (!inView) return;
    const timers = [
      setTimeout(() => setShowBadge(true), 100),
      setTimeout(() => setShowTitle(true), 280),
      setTimeout(() => setShowDesc(true),  460),
      setTimeout(() => setShowBtns(true),  620),
      setTimeout(() => setShowStats(true), 800),
      setTimeout(() => setShowCard(true),  200),
    ];
    return () => timers.forEach(clearTimeout);
  }, [inView]);

  /* Inject keyframes once */
  useEffect(() => {
    const id = 'hero-keyframes';
    if (document.getElementById(id)) return;
    const style = document.createElement('style');
    style.id = id;
    style.textContent = `
      @keyframes hero-fadeUp {
        from { opacity: 0; transform: translateY(28px); }
        to   { opacity: 1; transform: translateY(0); }
      }
      @keyframes hero-fadeIn {
        from { opacity: 0; }
        to   { opacity: 1; }
      }
      @keyframes hero-slideLeft {
        from { opacity: 0; transform: translateX(50px); }
        to   { opacity: 1; transform: translateX(0); }
      }
      @keyframes hero-float {
        0%, 100% { transform: translateY(0px); }
        50%       { transform: translateY(-10px); }
      }
      @keyframes hero-shimmer {
        0%   { background-position: -600px 0; }
        100% { background-position: 600px 0; }
      }
    `;
    document.head.appendChild(style);
  }, []);

  return (
    <section
      ref={sectionRef}
      id="about"
      className="pt-36 pb-28 px-6 min-h-screen flex items-center bg-gradient-to-br from-white via-primary-50 to-primary-100/40"
    >
      <div className="max-w-[1400px] mx-auto w-full">
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-16 items-center">

          {/* Content */}
          <div>

            {/* Badge */}
            <div style={{ opacity: 0, ...(showBadge && { animation: 'hero-fadeIn 0.5s cubic-bezier(.22,1,.36,1) forwards' }) }}>
              <span className="inline-block bg-primary-100 text-primary-700 px-5 py-2 rounded-full text-sm font-semibold mb-8">
                Качественное образование
              </span>
            </div>

            {/* Title */}
            <div style={{ opacity: 0, ...(showTitle && { animation: 'hero-fadeUp 0.7s cubic-bezier(.22,1,.36,1) forwards' }) }}>
              <h1 className="text-5xl md:text-6xl xl:text-7xl font-bold text-gray-900 mb-8 leading-tight tracking-tight">
                {data?.title}
              </h1>
            </div>

            {/* Description */}
            <div style={{ opacity: 0, ...(showDesc && { animation: 'hero-fadeUp 0.65s cubic-bezier(.22,1,.36,1) forwards' }) }}>
              <p className="text-xl text-gray-700 mb-10 leading-relaxed max-w-xl">
                {data?.description ||
                  'Институт бизнеса и делового администрирования Российской академии народного хозяйства и государственной службы при Президенте Российской Федерации готовит специалистов высочайшего уровня.'}
              </p>
            </div>

            {/* Buttons */}
            <div
              className="flex flex-col sm:flex-row gap-5"
              style={{ opacity: 0, ...(showBtns && { animation: 'hero-fadeUp 0.6s cubic-bezier(.22,1,.36,1) forwards' }) }}
            >
              <button
                className="bg-primary-600 text-white px-10 py-4 rounded-xl text-lg font-semibold shadow-lg hover:shadow-xl hover:bg-primary-700 transition flex items-center gap-2"
                style={{ transition: 'transform 0.2s ease, box-shadow 0.2s ease, background-color 0.2s ease' }}
                onMouseEnter={e => e.currentTarget.style.transform = 'translateY(-2px)'}
                onMouseLeave={e => e.currentTarget.style.transform = 'translateY(0)'}
              >
                Узнать больше
                <ArrowRight size={20} />
              </button>

              <button
                className="border-2 border-primary-600 text-primary-600 px-10 py-4 rounded-xl text-lg font-semibold hover:bg-primary-50 transition"
                style={{ transition: 'transform 0.2s ease, background-color 0.2s ease' }}
                onMouseEnter={e => e.currentTarget.style.transform = 'translateY(-2px)'}
                onMouseLeave={e => e.currentTarget.style.transform = 'translateY(0)'}
              >
                Поступить
              </button>
            </div>

            {/* Stats */}
            <div
              className="grid grid-cols-3 gap-10 mt-16"
              style={{ opacity: 0, ...(showStats && { animation: 'hero-fadeUp 0.7s cubic-bezier(.22,1,.36,1) forwards' }) }}
            >
              <div>
                <p className="text-4xl font-bold text-primary-600">
                  <AnimatedCounter target={data?.students_count || '1000+'} start={showStats} duration={1600} />
                </p>
                <p className="text-gray-600 mt-1">Студентов</p>
              </div>
              <div>
                <p className="text-4xl font-bold text-primary-600">
                  <AnimatedCounter target={data?.programs_count || '25+'} start={showStats} duration={1700} />
                </p>
                <p className="text-gray-600 mt-1">Программ</p>
              </div>
              <div>
                <p className="text-4xl font-bold text-primary-600">
                  <AnimatedCounter target={data?.founded_year || '1994'} start={showStats} duration={1800} />
                </p>
                <p className="text-gray-600 mt-1">Год основания</p>
              </div>
            </div>

          </div>

          {/* Visual — slider */}
          <div
            className="relative"
            style={{
              opacity: 0,
              ...(showCard && {
                animation: 'hero-slideLeft 0.8s cubic-bezier(.22,1,.36,1) forwards, hero-float 6s ease-in-out infinite 1s',
              }),
            }}
          >
            <div className="absolute inset-0 bg-gradient-to-br from-primary-400 to-primary-700 rounded-3xl opacity-20 blur-2xl" />
            <HeroSlider slides={slides} />
          </div>

        </div>
      </div>
    </section>
  );
};

export default HeroSection;